// The animations the finger pass is told about (the published word's id). PullE / LoadE = e's (its hand rows are a's, its shell its own).
// PullPe / LoadPe / OpenPe = the single-shot's (2026-11-09).
// LoadSch = the Schofield's (and the gate revolvers') push; FanSch / FanSix / FanWalker / Bottle / Cord = Jay's static poses (one frame).
enum class DbAnim {
    None = 0, Open = 1, Pull = 2, Load = 3, PullE = 4, LoadE = 5, PullPe = 6, LoadPe = 7, OpenPe = 8, LoadSch = 9, FanSch = 10, FanSix = 11,
    FanWalker = 12, Bottle = 13, Cord = 14, LoadSix = 15, LoadWalker = 16, HoldSix = 17, HoldWalker = 18   // RG6: the gate guns' held pose
};
constexpr int kDbAnimMaxId = 18;
constexpr int kSchLoadFrames = static_cast<int>(sizeof(kSchLoad) / sizeof(kSchLoad[0]));
constexpr int kSixLoadFrames = static_cast<int>(sizeof(kSixLoad) / sizeof(kSixLoad[0]));
constexpr int kWalkerLoadFrames = static_cast<int>(sizeof(kWalkerLoad) / sizeof(kWalkerLoad[0]));

inline bool DbStaticPose(DbAnim a)
{
    return a == DbAnim::Open || a == DbAnim::OpenPe || a == DbAnim::FanSch || a == DbAnim::FanSix || a == DbAnim::FanWalker ||
           a == DbAnim::Bottle || a == DbAnim::Cord || a == DbAnim::HoldSix || a == DbAnim::HoldWalker;
}
inline int DbAnimFrames(DbAnim a)
{
    return DbStaticPose(a) ? 1 : a == DbAnim::Pull ? kDbPullFrames : a == DbAnim::Load ? kDbLoadFrames
         : a == DbAnim::PullE ? kDbEPullFrames : a == DbAnim::LoadE ? kDbELoadFrames
         : a == DbAnim::PullPe ? kDbPePullFrames : a == DbAnim::LoadPe ? kDbPeLoadFrames : a == DbAnim::LoadSch ? kSchLoadFrames
         : a == DbAnim::LoadSix ? kSixLoadFrames : a == DbAnim::LoadWalker ? kWalkerLoadFrames : 0;
}

// Frame k (1-based) of an animation, clamped into the table. None / out of range clamps (never a read off the end).
inline const DbFrame& DbFrameAt(DbAnim a, int k)
{
    if (a == DbAnim::OpenPe) { return kDbPeOpen[0]; }
    if (a == DbAnim::FanSch) { return kFanSch[0]; }
    if (a == DbAnim::FanSix) { return kFanSix[0]; }
    if (a == DbAnim::FanWalker) { return kFanWalker[0]; }
    if (a == DbAnim::Bottle) { return kBottle[0]; }
    if (a == DbAnim::Cord) { return kCord[0]; }
    if (a == DbAnim::LoadSch) { return kSchLoad[k < 1 ? 0 : (k > kSchLoadFrames ? kSchLoadFrames - 1 : k - 1)]; }
    if (a == DbAnim::LoadSix) { return kSixLoad[k < 1 ? 0 : (k > kSixLoadFrames ? kSixLoadFrames - 1 : k - 1)]; }
    if (a == DbAnim::LoadWalker) { return kWalkerLoad[k < 1 ? 0 : (k > kWalkerLoadFrames ? kWalkerLoadFrames - 1 : k - 1)]; }
    if (a == DbAnim::HoldSix) { return kSixHold[0]; }
    if (a == DbAnim::HoldWalker) { return kWalkerHold[0]; }
    const int n = DbAnimFrames(a);
    if (n <= 1) { return kDbOpen[0]; }
    if (k < 1) { k = 1; }
    if (k > n) { k = n; }
    return a == DbAnim::Pull ? kDbPull[k - 1] : a == DbAnim::Load ? kDbLoad[k - 1] : a == DbAnim::PullE ? kDbEPull[k - 1]
         : a == DbAnim::LoadE ? kDbELoad[k - 1] : a == DbAnim::PullPe ? kDbPePull[k - 1] : kDbPeLoad[k - 1];
}

