inline bool   DbOneChamber(int set) { return set == kDbSetE || set == kDbSetPe; }
inline int    DbChambers(int set) { return DbOneChamber(set) ? 1 : 2; }
inline DbAnim DbPullAnim(int set) { return set == kDbSetPe ? DbAnim::PullPe : set == kDbSetE ? DbAnim::PullE : DbAnim::Pull; }
inline DbAnim DbLoadAnim(int set) { return set == kDbSetPe ? DbAnim::LoadPe : set == kDbSetE ? DbAnim::LoadE : DbAnim::Load; }
inline DbAnim DbOpenAnim(int set) { return set == kDbSetPe ? DbAnim::OpenPe : DbAnim::Open; }
inline bool   DbIsPull(DbAnim a) { return a == DbAnim::Pull || a == DbAnim::PullE || a == DbAnim::PullPe; }
inline bool   DbIsLoad(DbAnim a) { return a == DbAnim::Load || a == DbAnim::LoadE || a == DbAnim::LoadPe; }
inline int    DbPullFramesOf(int set) { return set == kDbSetPe ? kDbPePullFrames : set == kDbSetE ? kDbEPullFrames : kDbPullFrames; }
inline int    DbLoadFramesOf(int set) { return set == kDbSetPe ? kDbPeLoadFrames : set == kDbSetE ? kDbELoadFrames : kDbLoadFrames; }
inline int    DbSeatFrameOf(int set, int ch)
{
    return set == kDbSetPe ? kDbPeLoadSeatFrame : set == kDbSetE ? kDbELoadSeatFrame : kDbLoadSeatFrame[ch & 1];
}
inline int    DbOneStartOf(int set) { return DbOneChamber(set) ? 1 : kDbLoadOneStart; }
